(* [comment removed for export] *)
Definition hkept (P : Prop) : Prop := P.
Lemma hkept_intro : forall P : Prop, P -> hkept P. Proof. intros P p. exact p. Qed.
Lemma hkept_elim : forall P : Prop, hkept P -> P. Proof. intros P p. exact p. Qed.
Ltac hkeep H := apply hkept_intro in H.
Ltac hunkeep H := apply hkept_elim in H.

