(* [comment removed for export] *)
Lemma rw_cells_nth_chunk : forall m A (pre : list cell) (c : cell) (post : list cell),
  rw_cells bsegs m A (pre ++ c :: post) -> rw_cells bsegs m (A + Z.of_nat (cells_size pre)) [c].
Proof.
  intros m A pre c post R. apply (proj1 (rw_cells_app bsegs m A pre (c :: post))) in R. destruct R as [_ R].
  apply (proj1 (rw_cells_app bsegs m _ [c] post)) in R. destruct R as [R _]. exact R.
Qed.

